CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "ime" varchar not null, "prezime" varchar not null, "email" varchar not null, "password" varchar not null, "role" varchar check ("role" in ('admin', 'bibliotekar', 'clan')) not null default 'clan', "broj_clanske_karte" varchar, "telefon" varchar, "adresa" varchar, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "zanrovi" ("id" integer primary key autoincrement not null, "naziv" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "knjige" ("id" integer primary key autoincrement not null, "in_broj" integer, "naziv_knjige" varchar not null, "signatura" varchar, "autor" varchar, "datum" date, "izdavac" varchar, "nacin_nabavke" varchar, "isbn" varchar, "opis" text, "slika" varchar, "je_eknjiga" tinyint(1) not null default '0', "eknjiga_link" varchar, "created_at" datetime, "updated_at" datetime, mesto_izdavanja varchar, godina_izdavanja integer);
CREATE TABLE "knjiga_zanr" ("id" integer primary key autoincrement not null, "knjiga_id" integer not null, "zanr_id" integer not null, foreign key("knjiga_id") references "knjige"("id") on delete cascade, foreign key("zanr_id") references "zanrovi"("id") on delete cascade);
CREATE TABLE "primerci_knjiga" ("id" integer primary key autoincrement not null, "knjiga_id" integer not null, "inventarski_broj" integer not null, "signatura" varchar, "status" varchar not null default 'slobodna', "lokacija" varchar, "nacin_nabavke" varchar, "cena" numeric, "datum_unosa" date, "created_at" datetime, "updated_at" datetime, foreign key("knjiga_id") references "knjige"("id") on delete cascade);
CREATE TABLE "rezervacije" ("id" integer primary key autoincrement not null, "user_id" integer not null, "knjiga_id" integer not null, "primerak_id" integer, "odobrio_admin_id" integer, "status" varchar not null default 'na_cekanju', "datum_rezervacije" datetime, "datum_isteka" datetime, "datum_odobrenja" datetime, "rok_preuzimanja" datetime, "datum_preuzimanja" datetime, "datum_vracanja" datetime, "vracena" tinyint(1) not null default '0', "napomena" text, "created_at" datetime, "updated_at" datetime, "otkazana_vidjena" tinyint(1) not null default '0', foreign key("user_id") references "users"("id") on delete cascade, foreign key("knjiga_id") references "knjige"("id") on delete cascade, foreign key("primerak_id") references "primerci_knjiga"("id") on delete set null, foreign key("odobrio_admin_id") references "users"("id") on delete set null);
CREATE TABLE "zaduzivanja" ("id" integer primary key autoincrement not null, "user_id" integer not null, "clan_id" integer, "primerak_id" integer not null, "rezervacija_id" integer, "datum_izdavanja" date not null, "rok_vracanja" date not null, "datum_vracanja" date, "status" varchar not null default 'aktivno', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("clan_id") references "users"("id") on delete set null, foreign key("primerak_id") references "primerci_knjiga"("id") on delete cascade, foreign key("rezervacija_id") references "rezervacije"("id") on delete set null);
CREATE TABLE "arhiva" ("id" integer primary key autoincrement not null, "rezervacija_id" integer, "user_id" integer, "knjiga_id" integer, "tip" varchar not null, "naziv_knjige" varchar, "autor" varchar, "ime_clana" varchar, "email_clana" varchar, "broj_clanske_karte" varchar, "datum_akcije" datetime, "rok_vracanja" date, "created_at" datetime, "updated_at" datetime, foreign key("rezervacija_id") references "rezervacije"("id") on delete set null, foreign key("user_id") references "users"("id") on delete set null, foreign key("knjiga_id") references "knjige"("id") on delete set null);
CREATE TABLE "predlozi_knjiga" ("id" integer primary key autoincrement not null, "user_id" integer not null, "naziv" varchar not null, "autor" varchar, "obrazlozenje" text, "status" varchar not null default 'na_cekanju', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "activity_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "akcija" varchar not null, "opis" text, "model_tip" varchar, "model_id" integer, "stari_podaci" text, "novi_podaci" text, "ip_address" varchar, "user_agent" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
CREATE TABLE "najnovije_knjige" ("id" integer primary key autoincrement not null, "knjiga_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("knjiga_id") references "knjige"("id") on delete cascade);
CREATE TABLE "ai_conversations" ("id" integer primary key autoincrement not null, "user_id" integer not null, "naslov" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "ai_messages" ("id" integer primary key autoincrement not null, "conversation_id" integer not null, "role" varchar not null, "content" text not null, "created_at" datetime, "updated_at" datetime, foreign key("conversation_id") references "ai_conversations"("id") on delete cascade);
CREATE TABLE "knjige_embeddings" ("knjiga_id" integer not null, "embedding" text not null, primary key ("knjiga_id"));
CREATE TABLE "nauceni_primeri" ("id" integer primary key autoincrement not null, "pitanje" text not null, "odgovor" text not null, "pitanje_norm" varchar not null, "embedding" text not null, "izvor" varchar not null default 'few-shot', "aktivan" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "notifikacije" ("id" integer primary key autoincrement not null, "user_id" integer not null, "rezervacija_id" integer, "tip" varchar not null, "poruka" text not null, "procitano" tinyint(1) not null default ('0'), "created_at" datetime, "updated_at" datetime, "zaduzivanje_id" integer, foreign key("rezervacija_id") references rezervacije("id") on delete set null on update no action, foreign key("user_id") references users("id") on delete cascade on update no action, foreign key("zaduzivanje_id") references "zaduzivanja"("id") on delete set null);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE UNIQUE INDEX "users_broj_clanske_karte_unique" on "users" ("broj_clanske_karte");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE UNIQUE INDEX "zanrovi_naziv_unique" on "zanrovi" ("naziv");
CREATE UNIQUE INDEX "knjiga_zanr_knjiga_id_zanr_id_unique" on "knjiga_zanr" ("knjiga_id", "zanr_id");
CREATE UNIQUE INDEX "primerci_knjiga_inventarski_broj_unique" on "primerci_knjiga" ("inventarski_broj");
CREATE UNIQUE INDEX "najnovije_knjige_knjiga_id_unique" on "najnovije_knjige" ("knjiga_id");
CREATE UNIQUE INDEX "nauceni_primeri_pitanje_norm_unique" on "nauceni_primeri" ("pitanje_norm");
